  "selected" INTEGER,
  "output_kind" TEXT,
  "frozen_at_utc" TEXT,
  "source_repository" TEXT,
  "source_commit" TEXT,
  "artifact_path" TEXT,
  "artifact_sha256" TEXT,
  "alarm_policy" TEXT,
  "spec" TEXT
);

-- 追加式预测台账；当前内容为 v2 冻结台账（12 个候选 × 81,235 原点）的评分。
CREATE TABLE "prediction" (
  "model_id" INTEGER NOT NULL,
  "ts" INTEGER NOT NULL,
  "score" REAL,
  PRIMARY KEY ("model_id", "ts")
) WITHOUT ROWID;

-- v2 冻结评估发出的报警（gru_16 与 hgb_depth2）；score 是未校准评分，不是概率。
CREATE TABLE "alarm" (
  "alarm_id" INTEGER PRIMARY KEY,
  "model_id" INTEGER,
  "ts" INTEGER,
  "split" TEXT,
  "origin_index" INTEGER,
  "time" TEXT,
  "cycle_id" TEXT,
  "score" REAL,
  "anchor_id" TEXT,
  "matched_event" TEXT,
  "event_id" TEXT,
  "false_alarm" INTEGER,
  "unknown" INTEGER,
  "post_event" INTEGER
);

-- v2 冻结评估的逐事件结果（12 候选 × 10 个 EOL 事件）。
CREATE TABLE "event_result" (
  "model_id" INTEGER NOT NULL,
  "split" TEXT,
  "event_id" TEXT NOT NULL,
  "cycle_id" TEXT,
  "time" TEXT,
  "deadline" TEXT,
  "first_alarm" TEXT,
  "lead_minutes" REAL,
  "hit20" INTEGER,
  "excess_minutes" REAL,
  "late" INTEGER,
  "missed" INTEGER,
  "matched_alarm_count" INTEGER,
  "all_episode_first" TEXT,
  "earlier_alarm_count" INTEGER,
  "maximum_observable_lead_minutes" REAL,
  "latest_deadline_origin" TEXT,
  "latest_deadline_lead_minutes" REAL,
  "observable_origin_count" INTEGER,
  "deadline_origin_count" INTEGER,
  PRIMARY KEY ("model_id", "event_id")
) WITHOUT ROWID;

CREATE TABLE live_sample (
  tag_id            INTEGER NOT NULL,
  source_time_us    INTEGER NOT NULL,   -- OPC UA SourceTimestamp, UTC, microseconds since 1970
  server_time_us    INTEGER,            -- OPC UA ServerTimestamp (Kepware), UTC
  received_time_us  INTEGER NOT NULL,   -- collector clock when the notification arrived, UTC
  value             REAL,               -- NULL when the value is not numeric or the read was bad
  value_text        TEXT,               -- string tags (Gun_ID.DATA) and unparseable values
  status_code       INTEGER NOT NULL,   -- raw OPC UA StatusCode (0 = Good)
  session_id        TEXT NOT NULL,
  PRIMARY KEY (tag_id, source_time_us)
) WITHOUT ROWID;

CREATE TABLE collector_heartbeat (
  time_us           INTEGER NOT NULL,   -- collector clock, UTC
  session_id        TEXT NOT NULL,
  connected         INTEGER NOT NULL,   -- 1 while the OPC UA session answered the last check
  monitored_items   INTEGER NOT NULL,
  notifications     INTEGER NOT NULL,   -- data changes received since the previous heartbeat
  spool_rows        INTEGER NOT NULL,   -- rows waiting in the local store-and-forward buffer
  PRIMARY KEY (session_id, time_us)
) WITHOUT ROWID;

CREATE TABLE ingest_event (
  event_id          INTEGER PRIMARY KEY,
  time_us           INTEGER NOT NULL,
  session_id        TEXT,
  kind              TEXT NOT NULL,      -- session_start / session_lost / reconnect / subscribe_failed / sink_down / sink_up / bad_status / stale_tag
  tag_id            INTEGER,
  detail            TEXT
);

CREATE TABLE sqlite_stat1(tbl,idx,stat);

CREATE INDEX "ix_tag_field_key" ON "tag" ("field_key");

CREATE INDEX "ix_ingest_gap_last_ts_before" ON "ingest_gap" ("last_ts_before");

CREATE INDEX "ix_quality_event_ts" ON "quality_event" ("ts");

CREATE INDEX "ix_target_event_cycle_id" ON "target_event" ("cycle_id");

CREATE INDEX "ix_product_failure_event_v1_cycle_id" ON "product_failure_event_v1" ("cycle_id");

CREATE INDEX "ix_product_failure_event_v1_product_id" ON "product_failure_event_v1" ("product_id");

CREATE INDEX "ix_product_cycle_id" ON "product" ("cycle_id");

CREATE INDEX "ix_product_start_ts" ON "product" ("start_ts");

CREATE INDEX "ix_product_failure" ON "product" ("failure");

CREATE INDEX "ix_label_sample_cycle_id" ON "label_sample" ("cycle_id");

CREATE INDEX "ix_anchor_cycle_id" ON "anchor" ("cycle_id");

CREATE INDEX "ix_anchor_split" ON "anchor" ("split");

CREATE INDEX "ix_anchor_product_id" ON "anchor" ("product_id");

CREATE INDEX "ix_anchor_feature_28_cycle_id" ON "anchor_feature_28" ("cycle_id");

CREATE INDEX "ix_anchor_feature_28_in_v2" ON "anchor_feature_28" ("in_v2");

CREATE INDEX "ix_alarm_model_id" ON "alarm" ("model_id");

CREATE INDEX "ix_alarm_ts" ON "alarm" ("ts");

CREATE INDEX ix_live_sample_time ON live_sample (source_time_us);

CREATE TRIGGER prediction_no_update BEFORE UPDATE ON prediction
  BEGIN SELECT RAISE(ABORT, 'prediction ledger is append-only: publish a new model version instead'); END;

CREATE TRIGGER prediction_no_delete BEFORE DELETE ON prediction
  BEGIN SELECT RAISE(ABORT, 'prediction ledger is append-only'); END;

CREATE VIEW v_sample_1hz AS
  SELECT datetime(ts, 'unixepoch') AS ts_local, s.* FROM sample_1hz s;

CREATE VIEW v_tag_opcua AS
  SELECT t.tag_id, t.field_key, t.kepware_tag, t.opcua_node_id, t.node_id_confirmed, t.unit,
         t.scan_rate_ms, t.deadband_abs, t.in_history, t.reserved, t.model_v2_input
  FROM tag t ORDER BY t.tag_id;

CREATE VIEW v_anchor_supervised AS
  SELECT a.*, t.y_eol_30m, t.y_eol_45m, t.y_eol_60m, t.y_pre20_40m
  FROM anchor a JOIN target t USING (ts);

CREATE VIEW v_eol_event AS
  SELECT e.event_id, e.cycle_id, c.split, e.time, e.ts, e.deadline_20m, e.run_length, e.product_ids,
         e.second_completion AS v1_endpoint, c.end_type, c.end_evidence
  FROM target_event e JOIN electrode_cycle c USING (cycle_id) WHERE e.is_eol = 1;

CREATE VIEW v_cycle_summary AS
  SELECT c.cycle_id, c.split, c.usable_start, c.usable_end, c.end_type, c.eol_endpoint,
         c.right_censored, c.preventive_end, c.left_censored, c.product_count, c.eligible_products,
         c.failure_products, c.voltage_failed_products, c.feed_failed_products, c.pressure_failed_products,
         c.observed_on_hours, c.recorded_old_electrode_hours, c.unknown_clock_hours,
         (SELECT COUNT(*) FROM anchor a WHERE a.cycle_id = c.cycle_id) AS anchors,
         (SELECT COUNT(*) FROM anchor a WHERE a.cycle_id = c.cycle_id AND a.has_raw_1hz = 1) AS anchors_with_raw_1hz,
         (SELECT COUNT(*) FROM anchor a WHERE a.cycle_id = c.cycle_id AND a.remaining_seconds IS NOT NULL) AS anchors_with_remaining,
         (SELECT COUNT(*) FROM target_event e WHERE e.cycle_id = c.cycle_id AND e.is_eol = 1) AS eol_events,
         (SELECT COUNT(*) FROM target_event e WHERE e.cycle_id = c.cycle_id AND e.is_eol = 0) AS other_run_events
  FROM electrode_cycle c ORDER BY c.cycle_id;

CREATE VIEW v_day_coverage AS
  WITH days AS (
    SELECT date FROM raw_day UNION SELECT substr(timestamp, 1, 10) FROM anchor UNION SELECT substr(start, 1, 10) FROM product),
  a AS (SELECT substr(timestamp, 1, 10) AS date, COUNT(*) AS anchors FROM anchor GROUP BY 1),
  p AS (SELECT substr(start, 1, 10) AS date, COUNT(*) AS products, SUM(failure = 1) AS failed_products,
               SUM(failure IS NULL) AS unlabelled_products FROM product GROUP BY 1)
  SELECT d.date, r.rows AS raw_rows, r.missing_seconds AS raw_missing_seconds, r.powered_seconds,
         COALESCE(a.anchors, 0) AS anchors, COALESCE(p.products, 0) AS products,
         COALESCE(p.failed_products, 0) AS failed_products, COALESCE(p.unlabelled_products, 0) AS unlabelled_products,
         CASE WHEN r.rows IS NULL THEN 'curated_only' WHEN a.anchors IS NULL AND p.products IS NULL THEN 'raw_only' ELSE 'both' END AS coverage
  FROM days d LEFT JOIN raw_day r USING (date) LEFT JOIN a USING (date) LEFT JOIN p USING (date) ORDER BY d.date;

CREATE VIEW v_prediction AS
  SELECT m.name AS model, m.version, p.ts, datetime(p.ts, 'unixepoch') AS ts_local, p.score, m.threshold,
         m.alarm_enabled, m.selected
  FROM prediction p JOIN model_registry m USING (model_id);
